import{_ as e,o,c as d,a3 as a}from"./chunks/framework.cNy3aYYk.js";const u=JSON.parse('{"title":"Payroll 1.4.0 — Mark Paid Paid-from Bank Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Payroll 1.4.0 — Mark Paid Paid-from Bank Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/payroll-1-4-0-paid-from-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Payroll 1.4.0 — Mark Paid Paid-from Bank Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/payroll-1-4-0-paid-from-production-readiness"}]]},"headers":[],"relativePath":"deployment/payroll-1-4-0-paid-from-production-readiness.md","filePath":"deployment/payroll-1-4-0-paid-from-production-readiness.md","lastUpdated":1790450426000}'),r={name:"deployment/payroll-1-4-0-paid-from-production-readiness.md"};function n(s,t,i,c,l,p){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="payroll-1-4-0-—-mark-paid-paid-from-bank-production-readiness-audit" tabindex="-1">Payroll 1.4.0 — Mark Paid Paid-from Bank Production Readiness Audit <a class="header-anchor" href="#payroll-1-4-0-—-mark-paid-paid-from-bank-production-readiness-audit" aria-label="Permalink to &quot;Payroll 1.4.0 — Mark Paid Paid-from Bank Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-26 (remediation 2026-09-27)</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — all audit findings closed; migrate + SPA/Mobile before production Mark paid with Accounting</td></tr><tr><td><strong>Scope</strong></td><td>Tenant Payroll module <code>payroll</code> <strong>1.3.0 → 1.4.0</strong> (Mark paid requires Paid from cash/bank when Accounting entitled; auto-post accrual + payment journals)</td></tr><tr><td><strong>Companion</strong></td><td><a href="./payroll">Payroll ops</a> · <a href="./hr-phase7-production-readiness">Phase 7 HR readiness</a> · <a href="./accounting">Accounting</a> · <a href="/user-guide/payroll">User</a> · <a href="/developer-guide/payroll">Developer</a> · <a href="/api/tenant-v1-payroll">API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><p>Additive MINOR on Payroll. No new permissions, queues, scheduler entries, or env vars. Workspaces without Accounting keep status-only Mark paid. Workspaces with Accounting gain a required Paid-from picker and cash/bank balance decrease on pay.</p><p>This audit covers <strong>Payroll 1.4.0 paid-from only</strong>. Prior Phase 7 HR readiness remains valid for profiles / approve / pay slips.</p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>When <strong>Accounting</strong> is entitled, <strong>Mark paid</strong> on an approved pay run requires an active cash/bank <strong>Paid from</strong> account. The service:</p><ol><li>Ensures a <strong>posted</strong> accrual journal (<code>Dr</code> Salary Expense <code>6400</code> / <code>Cr</code> Salaries Payable <code>2200</code>) — creates+posts if missing, or posts an existing draft from <strong>Post to journal</strong>.</li><li>Creates+posts a <strong>payment</strong> journal (<code>Dr</code> Salaries Payable / <code>Cr</code> paid-from) via <code>CashMovementJournalService</code>.</li><li>Persists <code>paid_from_account_id</code>, accrual account FKs, <code>journal_entry_id</code>, and <code>payment_journal_entry_id</code>.</li></ol><p>Optional <strong>Post to journal</strong> still creates a <strong>draft</strong> accrual only. Locked accounting periods are enforced when journals are posted (<code>JournalEntryService::post</code> → <code>assertDateNotLocked</code>), covered by dedicated Pest.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Catalog <code>1.4.0</code> migrate-only bump</td><td><strong>Pass</strong></td></tr><tr><td>Schema additive + nullable account / payment JE columns</td><td><strong>Pass</strong></td></tr><tr><td>FK on <code>journal_entry_id</code> + <code>payment_journal_entry_id</code> → <code>journal_entries</code></td><td><strong>Pass</strong></td></tr><tr><td>Starter CoA <code>2200</code> / <code>6400</code> (+ <code>ensureMissingSystemAccounts</code>)</td><td><strong>Pass</strong> (<code>6100</code> remains Rent)</td></tr><tr><td>Accounting Mark paid requires cash/bank</td><td><strong>Pass</strong></td></tr><tr><td>Accrual ensure (missing / draft / posted)</td><td><strong>Pass</strong></td></tr><tr><td>Payment JE auto-posted (not draft)</td><td><strong>Pass</strong></td></tr><tr><td>Net ≤ 0 Mark paid rejected (Accounting)</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Locked period blocks Mark paid</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Without Accounting: status-only pay</td><td><strong>Pass</strong></td></tr><tr><td>Soft dep payroll → accounting (existing)</td><td><strong>Pass</strong></td></tr><tr><td>SPA Paid-from dialog (list / peek / view)</td><td><strong>Pass</strong></td></tr><tr><td>Mobile Paid-from picker</td><td><strong>Pass</strong></td></tr><tr><td>Pest <code>PayrollTest</code> (19)</td><td><strong>Pass</strong> (local 2026-09-27)</td></tr><tr><td>Docs + changelog + this page</td><td><strong>Pass</strong></td></tr><tr><td>CatalogSeeder payroll <code>version</code></td><td><strong>Pass</strong></td></tr><tr><td>Marketing payroll copy (Paid-from)</td><td><strong>Pass</strong></td></tr></tbody></table><p><strong>Go / No-Go:</strong> <strong>Go</strong> after companion CI and <code>php artisan migrate --force</code> <strong>before</strong> SPA/Mobile that send <code>paid_from_account_id</code>.</p><hr><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Status</th><th>Finding</th><th>Action</th></tr></thead><tbody><tr><td>F1</td><td>Medium</td><td><strong>Fixed</strong></td><td>CatalogSeeder payroll row omitted <code>version</code></td><td><code>&#39;version&#39; =&gt; &#39;1.4.0&#39;</code> on payroll in <code>CatalogSeeder</code></td></tr><tr><td>F2</td><td>Low</td><td><strong>Fixed</strong></td><td>Plan text said Salary Expense <code>6100</code> (already Rent)</td><td>Shipped <strong><code>6400</code> Salary Expense</strong>; docs/constants aligned</td></tr><tr><td>F3</td><td>Low</td><td><strong>Fixed</strong></td><td>No dedicated Pest for locked fiscal period on payroll pay</td><td>Added <code>blocks mark paid when the pay run period end falls in a locked accounting period</code></td></tr><tr><td>F4</td><td>Low</td><td><strong>Fixed</strong></td><td>No Pest for <code>net &lt;= 0</code> Mark paid reject</td><td>Added <code>rejects mark paid when accounting is entitled and net total is zero</code></td></tr><tr><td>F5</td><td>Low</td><td><strong>Fixed</strong></td><td><code>payment_journal_entry_id</code> (and legacy <code>journal_entry_id</code>) lacked FK</td><td>Migration <code>2026_09_26_190924_…</code> adds FKs → <code>journal_entries</code> <code>nullOnDelete</code></td></tr><tr><td>F6</td><td>Low</td><td><strong>Fixed</strong></td><td>Marketing payroll blurb omitted Paid-from</td><td>Website <code>lib/constants.ts</code> copy updated</td></tr></tbody></table><h3 id="accepted-intentional-not-defects" tabindex="-1">Accepted / intentional (not defects) <a class="header-anchor" href="#accepted-intentional-not-defects" aria-label="Permalink to &quot;Accepted / intentional (not defects)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Notes</th></tr></thead><tbody><tr><td>No new permissions</td><td>Reuse <code>payroll.pay</code> / <code>payroll.post</code></td></tr><tr><td>Draft accrual from Post</td><td>Cash movement rule: payment JE auto-posts; early accrual may stay draft until Mark paid</td></tr><tr><td>No WHT / unpay / void reverse</td><td>Explicitly out of scope for 1.4.0</td></tr><tr><td>Catalog bump ≠ auto-install</td><td>Workspaces without Payroll entitlement unchanged</td></tr><tr><td>Post to journal after paid-with-Accounting</td><td>Hidden once <code>journal_entry_id</code> is set</td></tr></tbody></table><hr><h2 id="plan-coverage-matrix" tabindex="-1">Plan coverage matrix <a class="header-anchor" href="#plan-coverage-matrix" aria-label="Permalink to &quot;Plan coverage matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan item</th><th>Result</th></tr></thead><tbody><tr><td><code>paid_from</code> / expense / liability / <code>payment_journal_entry_id</code> columns</td><td>Pass</td></tr><tr><td>Starter <code>2200</code> + salary expense code</td><td>Pass (<code>6400</code>)</td></tr><tr><td><code>markPaid</code> + <code>CashMovementJournalService</code></td><td>Pass</td></tr><tr><td><code>PayPayRunRequest</code> + controller</td><td>Pass</td></tr><tr><td>Resource nested journals / accounts</td><td>Pass</td></tr><tr><td>Catalog <strong>1.3.0 → 1.4.0</strong></td><td>Pass</td></tr><tr><td>Pest: cash drop / missing paid_from / no accounting / draft→pay</td><td>Pass</td></tr><tr><td>Pest: locked period + net ≤ 0</td><td>Pass</td></tr><tr><td>Journal entry FKs on pay run</td><td>Pass</td></tr><tr><td><code>.ai/rules/tenant.md</code> cash movements</td><td>Pass</td></tr><tr><td>Frontend dialog list/peek/view + e2e helper</td><td>Pass</td></tr><tr><td>Mobile picker + payload</td><td>Pass</td></tr><tr><td>User / dev / API / accounting docs + CHANGELOG</td><td>Pass</td></tr></tbody></table><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>php artisan test --compact tests/Feature/Tenant/Payroll/PayrollTest.php</code></td><td><strong>19 passed</strong> (local 2026-09-27)</td><td>Accounting pay cash drop, missing paid_from 422, no-accounting status-only, draft accrual then pay, net ≤ 0, locked period</td></tr><tr><td><code>tests/Feature/Tenant/Accounting/AccountTest.php</code></td><td><strong>7 passed</strong></td><td>Starter CoA; custom <code>6300</code> Marketing unaffected by <code>6400</code></td></tr><tr><td><code>npm run test:e2e:payroll</code> (or module suite)</td><td>Required green in CI</td><td><code>markPayRunPaidFromList</code> opens Paid-from dialog when Accounting entitled</td></tr></tbody></table><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li>Companion <strong>CI</strong> green (Backend / Frontend / Docs / Mobile as applicable)</li><li><strong>Backend</strong> — <code>php artisan migrate --force</code><ul><li><code>2026_09_26_182640_add_payroll_paid_from_and_payment_journal_to_pay_runs_table</code></li><li><code>2026_09_26_182643_bump_payroll_module_to_1_4_0</code></li><li><code>2026_09_26_190924_add_foreign_keys_to_pay_run_journal_entry_columns</code></li></ul></li><li>Confirm catalog <code>payroll</code> version <code>1.4.0</code> (no <code>db:seed</code>)</li><li>Confirm Accounts list backfills <code>2200</code> / <code>6400</code> via <code>ensureMissingSystemAccounts</code> (or first Mark paid / Post)</li><li><strong>SPA</strong> then <strong>Mobile</strong> — Paid-from UI must not ship before migrate</li><li><strong>Docs</strong> / Website (marketing copy)</li><li>Staging smoke below before production traffic</li></ol><p>Suggested merge: <strong>Backend → Frontend → Mobile → Docs</strong> (+ Website). Do <strong>not</strong> <code>db:seed</code>.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Pest <code>PayrollTest</code> green in CI (19)</td><td>Eng</td><td>☐</td></tr><tr><td>2</td><td>Playwright payroll suite green (Paid-from dialog path)</td><td>QA</td><td>☐</td></tr><tr><td>3</td><td>Migrations <code>182640</code> + <code>182643</code> + <code>190924</code> applied</td><td>Ops</td><td>☐</td></tr><tr><td>4</td><td>Catalog <code>payroll</code> version <code>1.4.0</code></td><td>Ops</td><td>☐</td></tr><tr><td>5</td><td>SPA/Mobile deployed <strong>after</strong> migrate</td><td>Ops</td><td>☐</td></tr><tr><td>6</td><td>Staging smoke signed off</td><td>QA / Ops</td><td>☐</td></tr></tbody></table><hr><h2 id="staging-smoke-human" tabindex="-1">Staging smoke (human) <a class="header-anchor" href="#staging-smoke-human" aria-label="Permalink to &quot;Staging smoke (human)&quot;">​</a></h2><ol><li>Marketplace → install <strong>Employees</strong>, <strong>Payroll</strong>, <strong>Accounting</strong> (free).</li><li>Open <strong>Accounts</strong> — confirm Cash <code>1000</code>, Salaries Payable <code>2200</code>, Salary Expense <code>6400</code> (or create cash/bank if needed). Seed cash via Set balance / opening journal so a credit is visible.</li><li>Create payroll profile + pay run → <strong>Approve</strong>.</li><li><strong>Mark paid</strong> without selecting Paid from → expect validation (dialog requires selection / API 422).</li><li><strong>Mark paid</strong> with Cash → status Paid; accrual + payment journals <strong>posted</strong>; Cash balance decreases by net total; Salaries Payable nets to zero for that run.</li><li>Optional path: on another approved run, <strong>Post to journal</strong> first (draft accrual) → <strong>Mark paid</strong> with bank → draft becomes posted + payment JE posted.</li><li>Workspace <strong>without</strong> Accounting: Mark paid one-click, no journals / no Paid from.</li><li>Locked fiscal period covering <code>period_end</code>: Mark paid fails with period lock validation; pay run stays <strong>approved</strong>.</li><li>Approved run with net <code>0.00</code>: Mark paid with Accounting fails validation; stays approved.</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Action</th></tr></thead><tbody><tr><td>Frontend / Mobile</td><td>Redeploy previous build (Paid-from UI disappears; columns remain)</td></tr><tr><td>Backend code</td><td>Redeploy previous release; leave columns (nullable)</td></tr><tr><td>Catalog</td><td>Optional <code>bumpVersion(&#39;payroll&#39;, &#39;1.3.0&#39;)</code> only if ops must show prior Marketplace version — prefer leave <code>1.4.0</code> if columns remain</td></tr><tr><td>Data</td><td>Do <strong>not</strong> drop payment/accrual journals already posted without a finance-approved void plan</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./payroll">Payroll production guide</a></li><li><a href="./hr-phase7-production-readiness">Phase 7 HR production readiness</a></li><li><a href="./accounting">Accounting deployment</a></li><li><a href="/changelog/">CHANGELOG — Payroll Mark paid → Paid from bank</a></li></ul>',38)])])}const h=e(r,[["render",n]]);export{u as __pageData,h as default};
